"""ResearchSpec: the structured form of a stated problem (the Problem API)."""

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class ResearchSpec:
    question: str
    max_papers: int = 10
    year_from: int | None = None

    def __post_init__(self) -> None:
        question = self.question.strip()
        if not question:
            raise ValueError("question must be non-empty")
        if len(question) > 2000:
            raise ValueError("question must be at most 2000 characters")
        if not 1 <= self.max_papers <= 50:
            raise ValueError("max_papers must be between 1 and 50")
        if self.year_from is not None and not 1900 <= self.year_from <= 2100:
            raise ValueError("year_from must be between 1900 and 2100")
        object.__setattr__(self, "question", question)

"""Retrieval from OpenAlex and Semantic Scholar, merged and deduped."""

from __future__ import annotations

import re

import httpx

from .papers import Paper
from .spec import ResearchSpec

OPENALEX_URL = "https://api.openalex.org/works"
SEMANTIC_SCHOLAR_URL = "https://api.semanticscholar.org/graph/v1/paper/search"
MAILTO = "autoresearch@example.com"  # polite OpenAlex contact; override via client


def _clean(text: str | None) -> str:
    if not text:
        return ""
    return re.sub(r"\s+", " ", text).strip()


def _openalex_abstract(inv_index: dict | None) -> str:
    if not inv_index:
        return ""
    try:
        pos: dict[int, str] = {}
        for word, idxs in inv_index.items():
            for i in idxs:
                pos[i] = word
        return " ".join(pos[i] for i in sorted(pos))
    except (TypeError, AttributeError):
        return ""


def openalex_search(spec: ResearchSpec, client: httpx.Client, limit: int = 25) -> list[Paper]:
    params: dict[str, str] = {
        "search": spec.question,
        "per-page": str(min(limit, 50)),
        "mailto": MAILTO,
    }
    if spec.year_from:
        params["filter"] = f"from_publication_date:{spec.year_from}-01-01"
    resp = client.get(OPENALEX_URL, params=params, timeout=30.0)
    resp.raise_for_status()
    out: list[Paper] = []
    for w in resp.json().get("results", []):
        doi = _clean((w.get("doi") or "").replace("https://doi.org/", ""))
        title = _clean(w.get("title"))
        if not title:
            continue
        authors = tuple(
            _clean(a.get("author", {}).get("display_name"))
            for a in w.get("authorships", [])[:10]
            if a.get("author", {}).get("display_name")
        )
        url = doi and f"https://doi.org/{doi}" or _clean(w.get("id"))
        out.append(
            Paper(
                ref=f"doi:{doi}" if doi else f"openalex:{w.get('id', '')}",
                title=title,
                abstract=_openalex_abstract(w.get("abstract_inverted_index")),
                authors=authors,
                year=w.get("publication_year"),
                venue=_clean((w.get("primary_location") or {}).get("source", {}).get("display_name") or ""),
                doi=doi,
                url=url,
                citations=int(w.get("cited_by_count") or 0),
                source="openalex",
            )
        )
    return out


def semscholar_search(spec: ResearchSpec, client: httpx.Client, limit: int = 25) -> list[Paper]:
    params = {
        "query": spec.question,
        "limit": str(min(limit, 50)),
        "fields": "title,abstract,authors,year,venue,doi,url,citationCount,externalIds",
    }
    if spec.year_from:
        params["year"] = f"{spec.year_from}-"
    resp = client.get(SEMANTIC_SCHOLAR_URL, params=params, timeout=30.0)
    resp.raise_for_status()
    out: list[Paper] = []
    for p in resp.json().get("data", []):
        title = _clean(p.get("title"))
        if not title:
            continue
        doi = _clean(p.get("doi") or "")
        authors = tuple(_clean(a.get("name")) for a in (p.get("authors") or [])[:10] if a.get("name"))
        url = _clean(p.get("url") or (doi and f"https://doi.org/{doi}")) or ""
        out.append(
            Paper(
                ref=f"doi:{doi.lower()}" if doi else f"s2:{p.get('paperId', '')}",
                title=title,
                abstract=_clean(p.get("abstract")),
                authors=authors,
                year=p.get("year"),
                venue=_clean(p.get("venue") or ""),
                doi=doi,
                url=url,
                citations=int(p.get("citationCount") or 0),
                source="semanticscholar",
            )
        )
    return out


def dedupe(papers: list[Paper]) -> list[Paper]:
    """Dedupe by DOI, else by normalized title. Keeps richer abstract."""
    seen: dict[str, Paper] = {}
    for p in papers:
        key = p.ref.lower() if p.ref.startswith("doi:") else "t:" + re.sub(r"\W+", "", p.title.lower())
        prev = seen.get(key)
        if prev is None or (not prev.abstract and p.abstract):
            seen[key] = p
    return list(seen.values())


def retrieve(spec: ResearchSpec, client: httpx.Client | None = None) -> list[Paper]:
    """Query both sources; degrade gracefully if one fails."""
    own = client is None
    client = client or httpx.Client()
    try:
        papers: list[Paper] = []
        errors: list[str] = []
        for fn in (openalex_search, semscholar_search):
            try:
                papers.extend(fn(spec, client))
            except (httpx.HTTPError, ValueError) as e:
                errors.append(f"{fn.__name__}: {e}")
        if not papers and errors:
            raise RuntimeError(f"retrieval failed: {'; '.join(errors)}")
        return dedupe(papers)
    finally:
        if own:
            client.close()

"""Muse API client (Meta Model API, OpenAI-compatible)."""

from __future__ import annotations

import os

BASE_URL = "https://api.meta.ai/v1"
DEFAULT_MODEL = "muse-spark-1.3"
KEY_VARS = ("MUSE_API_KEY", "MODEL_API_KEY", "META_API_KEY")


def resolve_api_key(env: dict | None = None) -> str:
    env = env if env is not None else os.environ
    for var in KEY_VARS:
        if env.get(var):
            return env[var]
    raise RuntimeError(
        "no Muse API key found; set MUSE_API_KEY (also accepts MODEL_API_KEY or META_API_KEY)"
    )


class MuseClient:
    """Thin wrapper over the OpenAI SDK pointed at the Muse API."""

    def __init__(self, api_key: str | None = None, model: str = DEFAULT_MODEL) -> None:
        from openai import OpenAI

        self.model = model
        self._client = OpenAI(api_key=api_key or resolve_api_key(), base_url=BASE_URL)

    def complete(self, system: str, user: str, max_tokens: int = 2000) -> str:
        resp = self._client.chat.completions.create(
            model=self.model,
            messages=[
                {"role": "system", "content": system},
                {"role": "user", "content": user},
            ],
            max_tokens=max_tokens,
        )
        return (resp.choices[0].message.content or "").strip()

"""Synthesis: Muse turns ranked papers into a cited review."""

from __future__ import annotations

import re
from dataclasses import dataclass
from typing import Protocol

from .papers import Paper

SYSTEM = (
    "You are a precise research assistant. Write a concise literature review "
    "from ONLY the papers provided. Every factual claim must carry a citation "
    "marker like [1], [2] referring to the numbered papers. If the papers do "
    "not support an answer, say so explicitly. End with 2-4 open questions."
)

_CITE_RE = re.compile(r"\[(\d+)\]")


class Completer(Protocol):
    model: str

    def complete(self, system: str, user: str, max_tokens: int = ...) -> str: ...


@dataclass(frozen=True)
class Synthesis:
    text: str
    cited: tuple[int, ...]
    model: str


def build_prompt(question: str, papers: list[Paper]) -> str:
    lines = [f"Research question: {question}", "", "Papers:"]
    for i, p in enumerate(papers, 1):
        authors = ", ".join(p.authors[:4]) or "unknown"
        lines.append(f"[{i}] {p.title} — {authors} ({p.year or 'n.d.'}). {p.venue}".strip())
        if p.abstract:
            lines.append(f"    Abstract: {p.abstract[:1200]}")
        if p.url:
            lines.append(f"    Link: {p.url}")
    lines += ["", "Write the review with [n] citations, then open questions."]
    return "\n".join(lines)


def cited_indices(text: str, n_papers: int) -> tuple[int, ...]:
    found = sorted({int(m) for m in _CITE_RE.findall(text) if 1 <= int(m) <= n_papers})
    return tuple(found)


def synthesize(question: str, papers: list[Paper], client: Completer) -> Synthesis:
    if not papers:
        raise ValueError("no papers to synthesize")
    text = client.complete(SYSTEM, build_prompt(question, papers))
    if not text.strip():
        raise RuntimeError("Muse API returned an empty synthesis")
    return Synthesis(text=text, cited=cited_indices(text, len(papers)), model=client.model)

